16	/// A path in a specific virtual file system root.
17	///
18	/// This identifies a location in a project or package.
19	#[derive(Clone, Eq, PartialEq, Hash)]
20	pub struct RootedPath {
21	    root: VirtualRoot,
22	    vpath: VirtualPath,
23	}
