25	impl RootedPath {
26	    /// Create a rooted path from a root and a virtual path within the root.
27	    pub fn new(root: VirtualRoot, vpath: VirtualPath) -> Self {
28	        Self { root, vpath }
29	    }
30	
31	    /// Turns this path into a `FileId`.
32	    pub fn intern(self) -> FileId {
33	        FileId::new(self)
34	    }
35	
